import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;

  // Create group for the sprite
  const group = new THREE.Group();
  group.userData.cleanup = () => {
    // Cleanup will be called by adapter
  };

  // Atlas region: 512x320 pixels
  // Assuming a 2048x2048 atlas (common standard)
  const atlasSize = 2048;
  const regionX = 0;
  const regionY = 0;
  const regionWidth = 512;
  const regionHeight = 320;

  // Calculate UV bounds for the atlas region
  const uMin = regionX / atlasSize;
  const vMin = regionY / atlasSize;
  const uMax = (regionX + regionWidth) / atlasSize;
  const vMax = (regionY + regionHeight) / atlasSize;

  // Aspect ratio: 512/320 = 1.6
  const aspectRatio = regionWidth / regionHeight;

  // Create plane geometry scaled to aspect ratio
  // Set a reasonable base height and scale width accordingly
  const planeHeight = 1.2;
  const planeWidth = planeHeight * aspectRatio;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight, 1, 1);

  // Adjust UVs to match atlas region
  const uvAttribute = geometry.getAttribute('uv');
  const uvArray = uvAttribute.array;

  // UV coordinates for the four corners of the plane
  // Bottom-left: (uMin, vMin)
  // Bottom-right: (uMax, vMin)
  // Top-left: (uMin, vMax)
  // Top-right: (uMax, vMax)
  uvArray[0] = uMin;
  uvArray[1] = vMin; // bottom-left

  uvArray[2] = uMax;
  uvArray[3] = vMin; // bottom-right

  uvArray[4] = uMin;
  uvArray[5] = vMax; // top-left

  uvArray[6] = uMax;
  uvArray[7] = vMax; // top-right

  uvAttribute.needsUpdate = true;

  // Load the ceramic grain texture
  let material;
  ctx.textureLoader.loadTexture(config.imageUrl).then((texture) => {
    // Configure texture
    texture.magFilter = THREE.LinearFilter;
    texture.minFilter = THREE.LinearMipmapLinearFilter;

    // Create MeshBasicNodeMaterial with texture mapping
    const textureNode = new THREE.TextureNode(texture, uv());
    material = new MeshBasicNodeMaterial();
    material.colorNode = textureNode;

    mesh.material = material;
  });

  // Create material first (will be replaced when texture loads)
  material = new MeshBasicNodeMaterial({
    color: 0xffffff,
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Billboard toward camera (face toward +Z)
  mesh.position.z = 0;

  group.add(mesh);

  // Create text label "Features 3"
  const textLabel = ctx.fontAtlas.createText('Features 3', {
    fontSize: 39,
    color: '#16161d',
    align: 'center',
  });

  // Position text below the sprite
  textLabel.position.y = -planeHeight / 2 - 0.3;
  textLabel.position.z = 0.01;

  group.add(textLabel);

  return group;
}
